$('chat-open').onclick=()=>{stopInputs();$('chat-panel').hidden=false;$('chat-input').focus();};$('chat-close').onclick=()=>{$('chat-input').blur();$('chat-panel').hidden=true;clearVisitChat();};$('chat-form').onsubmit=async e=>{e.preventDefault();const text=$('chat-input').value.trim();if(!text)return;if(!['host','admin'].includes(actors.get(selfId)?.state.role)&&!await Account.require('함께 대화를 나누려면 간편 로그인해 주세요.'))return;send({type:'chat',text,scope:$('chat-mode').value});$('chat-input').value='';if(campfire?.focused){$('chat-input').blur();$('chat-panel').hidden=true;}};$('chat-mode').onchange=()=>{if($('chat-mode').value==='whisper'&&!actors.get(selfId)?.state.seat){$('chat-mode').value='public';toast('같은 테이블이나 벤치에 앉은 뒤 귓속말을 선택해 주세요.');}const scope=$('chat-mode').value;$('chat-input').maxLength=scope==='shout'?100:180;};

function detail(html){delete $('detail-content').dataset.publicVersion;$('detail-content').innerHTML=html;$('detail').classList.toggle('ingredient-detail',!!$('detail-content').querySelector('.ingredient-reader'));$('detail').showModal();keys.clear();release();}
function scentCard(s){detail(`<div class="scent-visual" style="--bottle:${esc(s.color)}"><div class="scent-glass"></div></div><p class="tiny">${esc(s.family)}</p><h2>${esc(s.name)}</h2><div class="tag-row"><span>${esc(s.mood)}</span><span>${esc(s.notes)}</span></div><p>${esc(s.story)}</p><h3>소설 속 향과 기억</h3><p>『스완네 집 쪽으로』에서는 차와 마들렌의 감각이 오래된 기억을 불러옵니다. 이 향은 당신의 어떤 장면과 이어지나요?</p><a class="text-link" href="https://www.gutenberg.org/ebooks/7178" target="_blank" rel="noopener noreferrer">마르셀 프루스트 · 작품 정보 ↗</a><p class="muted">작품 내용을 공방의 말로 요약한 안내입니다.</p><button class="primary" data-favorite-scent="${esc(s.id)}">나의 향 취향으로 남기기 ♡</button>`);}
function booksCard(){detail(`<p class="tiny">THE READING SHELVES</p><h2>책장에 꽂힌 이야기</h2><p>책 소개와 아래의 향 문장은 공방에서 직접 작성했습니다. 작품 본문·번역문을 옮긴 인용이 아니에요.</p><button class="primary" data-open-board="books">책갈피 포스트잇 벽 보기 ↗</button>${content.books.map(b=>`<article class="book-card" style="--book-color:${esc(b.color)}"><p class="tiny">${esc(b.genre)} · ${esc(b.author||'책과향기')}</p><h3>${esc(b.name)}</h3><p>${esc(b.intro||b.line)}</p><p class="quote">${esc(b.line)}</p><p class="muted">책과향기 창작 문장</p><p>${esc(b.question)}</p><div class="book-actions"><button class="secondary" data-favorite-book="${esc(b.id)}">나의 책 취향 ♡</button><button class="secondary" data-discuss-book="${esc(b.id)}">이 책으로 대화하기</button><button class="secondary" data-board-book="${esc(b.id)}">추천·소개·한줄 남기기</button></div>${b.source?'<a class="text-link" href="'+esc(b.source)+'" target="_blank" rel="noopener noreferrer">작품 정보 출처 ↗</a>':''}</article>`).join('')}`);}
let activeBoard='books',boardBook='',notePage=0,lastNoteKey='';
function openBoard(board='books',book=''){activeBoard=board;boardBook=book;notePage=0;detail(`<p class="tiny">STORIES LEFT ON PAPER</p><h2>${board==='books'?'책갈피 포스트잇 벽':'향기카페의 작은 메모'}</h2><p>${transport?.publicDemo?'체험용 포스트잇은 이번 방문에만 남아요. 실제 공개 글은 홈페이지 방명록에 남겨주세요.':'추천하고 싶은 책, 함께 나눌 이야기, 오늘의 한줄을 붙여주세요.'}</p><form id="note-form"><label class="field">어떤 책에 남길까요?<select id="note-book"><option value="">모두에게 남기는 메모</option>${content.books.map(b=>'<option value="'+esc(b.id)+'" '+(book===b.id?'selected':'')+'>'+esc(b.name)+'</option>').join('')}</select></label><div class="note-categories"><label><input type="radio" name="note-category" value="recommend" checked>추천</label><label><input type="radio" name="note-category" value="intro">소개</label><label><input type="radio" name="note-category" value="line">한줄</label></div><label class="field">나의 포스트잇<textarea id="note-text" maxlength="120" rows="2" placeholder="직접 쓴 120자 이내의 이야기를 남겨주세요." required></textarea></label><button class="primary" type="submit">포스트잇 붙이기 ＋</button></form><div id="note-list" class="note-board"></div><nav class="note-pages"><button class="secondary" data-note-page="-1">이전</button><span id="note-page-label"></span><button class="secondary" data-note-page="1">다음</button></nav><p class="muted">이 공간에서 함께 나누는 메모입니다. 본인 메모는 삭제할 수 있으며 진행자는 모든 메모를 관리할 수 있어요.</p>`);renderNotes();}
function renderNotes(){if(!$('note-list'))return;const rows=(snapshot?.notes||[]).filter(n=>n.board===activeBoard&&(!boardBook||n.book===boardBook)).slice().reverse(),pages=Math.max(1,Math.ceil(rows.length/9));notePage=Math.max(0,Math.min(pages-1,notePage));const host=['host','admin'].includes(actors.get(selfId)?.state.role);$('note-list').innerHTML=rows.slice(notePage*9,notePage*9+9).map(n=>`<article class="reader-note" style="--paper:${esc(n.color)}"><small>${{recommend:'추천',intro:'소개',line:'한줄'}[n.category]} · ${esc(content.books.find(b=>b.id===n.book)?.name||'모두에게')}</small><p>${esc(n.text)}</p><footer><b>${esc(n.nickname)}</b><time>${new Intl.DateTimeFormat('ko-KR',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Seoul'}).format(n.at)}</time></footer>${n.mine||host?'<button data-delete-note="'+esc(n.id)+'">메모 삭제</button>':''}</article>`).join('')||'<p class="muted">첫 포스트잇의 주인공이 되어주세요.</p>';$('note-page-label').textContent=(notePage+1)+' / '+pages;}
$('detail-content').addEventListener('submit',e=>{if(e.target.id!=='note-form')return;e.preventDefault();send({type:'note',board:activeBoard,book:$('note-book').value,category:document.querySelector('[name="note-category"]:checked').value,text:$('note-text').value});});
$('detail-content').addEventListener('change',e=>{if(e.target.id==='note-book'){boardBook=e.target.value;notePage=0;renderNotes();}});
let balanceIndex=0;function balanceCard(){const b=BALANCE[balanceIndex%BALANCE.length];detail(`<p class="tiny">SCENT BALANCE · ${balanceIndex%BALANCE.length+1} / ${BALANCE.length}</p><h2>${esc(b.question)}</h2><p>정답은 없어요. 나와 더 닮은 쪽을 골라 이야기해 보세요.</p><button class="primary" data-balance="A">A · ${esc(b.a)}</button><button class="primary" data-balance="B">B · ${esc(b.b)}</button><button class="text-link" data-next-balance>다음 질문 →</button>`);}
$('interact').onclick=()=>{if(near?.type==='harvest'){harvest.open(near);return;}if(space==='garden'&&near?.type==='beyond'){goBeyond();return;}if(!near&&space==='camp'){campfire.begin();return;}if(!near){if(space==='books'){booksCard();return;}if(space==='scents'){detail('<p class="tiny">SCENT COLLECTION</p><h2>다섯 가지 향의 이야기</h2>'+content.scents.map(s=>'<button class="primary" data-view-scent="'+esc(s.id)+'">'+esc(s.family)+' · '+esc(s.name)+'</button>').join(''));return;}if(space==='salon'){detail('<h2>어느 자리에 앉을까요?</h2><button class="primary" data-open-board="cafe">카페 포스트잇 벽</button><p>빈 의자 가까이에서 멈추면 사뿐히 앉아요. 대화창에서 귓속말을 고르면 같은 테이블이나 바에 앉은 분들만 들을 수 있어요.</p>'+CAFE_TABLES.map(t=>'<p>'+esc(t.label)+'</p>').join(''));return;}near={type:space==='camp'?'camp-story':'today'};}if(near.type==='beyond'){transport?.close();location.assign('/beyond/');return;}if(near.type==='campfire'){campfire.begin();return;}if(near.type==='camp-story'){detail('<p class="tiny">CAMPFIRE SENTENCE</p><h2>별빛 아래, 잠시 쉬어가요.</h2><p class="quote">오늘의 이야기를 모닥불 곁에 잠시 내려놓아요.</p><p>통나무 의자 곁에서 멈추면 앉을 수 있어요. 공상 버튼에 지금의 생각을 적어보세요. 공상은 나에게만 보이고, 대화창의 말은 다른 참가자에게 전해져요.</p><p class="muted">책과향기 자체 작성 문장 · 아래쪽 입구로 돌아가면 햇살 정원의 숲길로 이어져요.</p>');return;}if(near.type==='solo')openSoloApplication();if(near.type==='compose')openArchiveBlend();if(near.type==='ingredient')museumGuide.openIngredient(near.id);if(near.type==='board')museumGuide.openPublicBoard();if(near.type==='scent')scentCard(content.scents.find(s=>s.id===near.id));if(near.type==='book')booksCard();if(near.type==='balance')balanceCard();if(near.type==='today')detail(`<p class="tiny">TODAY’S SCENT & SENTENCE</p><h2>편지 속의 장미</h2><p class="quote">오늘 만난 다정함을 주머니에 접어 넣었습니다.</p><p>꽃의 다정함과 깨끗한 머스크의 여백으로, 오늘의 이야기를 시작해 보세요.</p><p class="muted">책과향기 자체 작성 문장</p><p class="muted">정원 입구를 지나 로비로 들어오세요. 로비 왼쪽 문은 향기 아카이브로 이어집니다.</p>`);if(near.type==='table')social.requestSitNearest();};
$('detail-content').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.museumOil){send({type:'museum-oil',kind:b.dataset.museumOil,phase:'claim'});}if(b.dataset.openBoard){$('detail').close();openBoard(b.dataset.openBoard);}if(b.dataset.boardBook){$('detail').close();openBoard('books',b.dataset.boardBook);}if(b.dataset.notePage){notePage+=Number(b.dataset.notePage);renderNotes();}if(b.dataset.deleteNote)send({type:'delete-note',id:b.dataset.deleteNote});if(b.dataset.discussBook){const book=content.books.find(book=>book.id===b.dataset.discussBook);$('detail').close();$('chat-panel').hidden=false;$('chat-input').value='『'+book.name+'』 · '+book.question;$('chat-input').focus();}if(b.dataset.viewScent){const scent=content.scents.find(s=>s.id===b.dataset.viewScent);$('detail').close();if(scent)scentCard(scent);}if(b.dataset.selectTable){send({type:'table',table:Number(b.dataset.selectTable)});$('detail').close();toast('대화 테이블 '+b.dataset.selectTable+'을 선택했어요.');}if(b.dataset.favoriteScent){send({type:'profile',scent:b.dataset.favoriteScent});$('detail').close();toast('좋아하는 향을 프로필에 남겼어요.');}if(b.dataset.favoriteBook){send({type:'profile',book:b.dataset.favoriteBook});$('detail').close();toast('좋아하는 이야기를 프로필에 남겼어요.');}if(b.dataset.balance){send({type:'balance',value:b.dataset.balance});toast(b.dataset.balance+'를 선택했어요. 다른 분의 이야기도 들어보세요.');}if(b.hasAttribute('data-next-balance')){balanceIndex++;$('detail').close();balanceCard();}if(b.hasAttribute('data-visit-scents')){$('detail').close();toast('로비 왼쪽 문으로 걸어가 주세요.');}if(b.dataset.report){const reason=prompt('신고 내용을 200자 이내로 적어주세요.');if(reason)send({type:'report',target:b.dataset.report,reason});}if(b.dataset.like){send({type:'like',target:b.dataset.like,consent:$('contact-consent')?.checked===true});}if(b.dataset.noLike){send({type:'like',target:null,consent:false});}};
async function renderHost(){try{const d=await transport.admin();$('host-status').textContent='';const box=$('host-content');if(hostTab==='flow'){box.innerHTML=`<button class="primary" type="button" data-barista-duty>☕ 바리스타 자리에서 귓속말 대화하기</button><p class="tiny">카페 안에서 사용할 수 있어요. 바 좌석 손님과 대화하고, 일어나기로 돌아옵니다.</p><form id="host-flow"><label class="field">진행 단계<select name="phase">${PHASES.map((p,i)=>`<option value="${i}" ${d.meeting.phase===i?'selected':''}>${i+1}. ${p.name} · ${p.minutes}분</option>`).join('')}</select></label><div class="row"><button class="secondary" type="button" data-command="timer-start">타이머 시작</button><button class="secondary" type="button" data-command="timer-pause">일시정지</button><button class="secondary" type="button" data-command="groups">대화 그룹 재배치</button></div><label class="field">화면에 띄울 질문<textarea name="question" maxlength="200">${esc(d.meeting.question)}</textarea></label><button class="primary">질문 · 단계 적용</button></form><details><summary>모임 일정과 정원</summary><form id="meeting-form"><label class="field">모임명<input name="name" required maxlength="80" value="${esc(d.meeting.name)}"></label><label class="field">구성<select name="format">${['3:3','4:4','5:5'].map(f=>`<option ${f===d.meeting.format?'selected':''}>${f}</option>`).join('')}</select></label><label class="field">참가 조건<input name="ageCondition" value="${esc(d.meeting.ageCondition)}"></label>${[['startsAt','모임 시작'],['entryAt','입장 시작'],['deadline','신청 마감'],['endsAt','입장 종료']].map(([k,n])=>`<label class="field">${n} · 한국시간<input name="${k}" type="datetime-local" value="${new Date(d.meeting[k]+9*3600000).toISOString().slice(0,16)}" required></label>`).join('')}<label class="field">오픈채팅 주소<input name="openChat" type="url" placeholder="https://open.kakao.com/…" value="${esc(d.meeting.openChat||'')}"></label><button class="primary">모임 설정 저장</button></form></details><p class="tiny">총 수신 ${d.metrics.received} · 전송 ${d.metrics.sent} · 누적 ${(d.metrics.bytes/1024).toFixed(0)}KB · 최대 ${d.metrics.peak}명</p>`;}else if(hostTab==='members'){box.innerHTML=`<h3>참가 승인 · 성인 확인</h3><p>기존 솔로만 신청과 연락처를 대조한 뒤 성인 여부를 확인해 주세요. 체크박스 자기신고만으로 승인하지 않습니다.</p><div class="people-list">${d.members.map(m=>`<form class="person-row" data-member="${esc(m.id)}"><strong>${esc(m.nickname)} · ${esc(m.role)}</strong><select name="status">${[['received','신청 접수'],['waiting','대기'],['approved','승인'],['rejected','거절'],['cancelled','취소'],['completed','참가 완료']].map(([v,n])=>`<option value="${v}" ${m.status===v?'selected':''}>${n}</option>`).join('')}</select><select name="group"><option ${m.group==='A'?'selected':''}>A</option><option ${m.group==='B'?'selected':''}>B</option></select><label><input name="adultConfirmed" type="checkbox" ${m.adultConfirmed?'checked':''}> 성인 확인 완료</label><button>적용</button>${m.id!==selfId?`<button type="button" data-kick="${esc(m.id)}">강제 퇴장·차단</button>`:''}</form>`).join('')}</div>`;}else if(hostTab==='chat'){renderHostChat(box,d,renderHost);}else if(hostTab==='content'){box.innerHTML=`<h3>향·책 전시 콘텐츠</h3><p>향과 도서 오브제는 직접 작성한 설명을 사용하세요. 타인의 책 본문·표지·인용문을 허락 없이 업로드하지 마세요.</p><form id="content-form"><label class="field">전시 콘텐츠 JSON<textarea name="data" rows="16">${esc(JSON.stringify({scents:d.content.scents,books:d.content.books},null,2))}</textarea></label><button class="primary">전시 콘텐츠 저장</button></form>`;}else{box.innerHTML=`<h3>신고 ${d.reports.length}건</h3>${d.reports.map(r=>`<div class="book-card"><p>${esc(d.members.find(m=>m.id===r.target)?.nickname||r.target)}</p><p>${esc(r.reason)}</p><button class="secondary" data-kick="${esc(r.target)}">대상 차단·퇴장</button></div>`).join('')}<h3>상호 호감 + 연락 연결 동의</h3><p>개별 선택과 일방적 호감은 표시하지 않습니다.</p>${d.matches.length?d.matches.map(pair=>'<p class="quote">'+pair.map(id=>esc(d.members.find(m=>m.id===id)?.nickname||id)).join(' ♡ ')+'</p>').join(''):'<p>아직 상호 동의 결과가 없습니다.</p>'}<a class="text-link" href="https://naver.me/FQVGlhlr" target="_blank" rel="noopener noreferrer">책과향기 오프라인 모임으로 이어가기 ↗</a>`;}}catch(e){$('host-status').textContent=e.message;}}
